  foreach(var field in new[]{"Standard","Move","Swift","Initiative","Reaction","ReactionsRemaining","LastSurpriseTicks"}){var name=field;Check("every budget/reaction/surprise mutation remains a failure "+name,()=>{var archive=Fixture();World(archive);var native=Kingmaker.Game.Instance.State.Units[0].Native;typeof(SavedNativeActor).GetProperty(name).SetValue(native,name=="ReactionsRemaining"?(object)2:name=="LastSurpriseTicks"?(object)1L:(object)99f);var scenario=new Chunk7PersistenceScenario(new RuntimeRequest(),new MountedPersistenceService());Refuse(()=>scenario.Check(archive),"spent remainder");var row=scenario.Observations["combatDebtChecks"][0]["actors"][0];True(((JArray)row["fields"]).Any(value=>(string)value["field"]==name&&!(bool)value["passed"]),"Wrong field attribution.");});}
  foreach(var ticks in new[]{-1L,300000001L})Check("clock window is unchanged "+ticks,()=>{var archive=Fixture();World(archive);Kingmaker.Game.Instance.TimeController.GameTime=TimeSpan.FromTicks(archive.GameTimeTicks+ticks);var scenario=new Chunk7PersistenceScenario(new RuntimeRequest(),new MountedPersistenceService());Refuse(()=>scenario.Check(archive),"observation window");True(((JArray)scenario.Observations["combatDebtChecks"][0]["actors"]).Count==7,"Window failure lacked full diagnostics.");});
